import { spawn } from 'node:child_process';
import { closeSync, mkdtempSync, openSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

// #4770 (Codex XREVIEW P2). run-hook.mjs reads a regular-file stdin whole when
// fstatSync(0) says it is <= 512KB. If the file grows between that fstat and the
// read, the unbounded readFileSync(0) hands the whole payload to the hook and the
// 512KB guard is bypassed. The stream path refuses an oversized input; for the
// fail-closed gate skill/review-post-gate that refusal is exit 2.
//
// grow-stdin-after-stat.mjs grows the file right after the first fstatSync(0).
// The control arm runs the same small file without the growth, so the refusal
// can only come from the oversized read, not from the preload.

const RUN_HOOK = join(__dirname, '../../../bin/run-hook.mjs');
const GROW_PRELOAD = join(__dirname, 'grow-stdin-after-stat.mjs');
const GATE = 'skill/review-post-gate';
const MAX_STDIN_BYTES = 512 * 1024;
const SIZE_REFUSAL = /over the size limit/;
const SMALL = JSON.stringify({ tool_name: 'Bash', tool_input: { command: 'echo hi' } });

function runFileStdin(grow: boolean): Promise<{ code: number | null; stderr: string; fileSize: number }> {
  return new Promise((resolve) => {
    const dir = mkdtempSync(join(tmpdir(), 'ork-4770-'));
    const payloadPath = join(dir, 'payload.json');
    writeFileSync(payloadPath, SMALL);
    const fd = openSync(payloadPath, 'r');
    const child = spawn('node', ['--import', GROW_PRELOAD, RUN_HOOK, GATE], {
      stdio: [fd, 'pipe', 'pipe'],
      env: {
        ...process.env,
        CLAUDE_PROJECT_DIR: dir,
        ...(grow ? { ORK_TEST_GROW_STDIN_PATH: payloadPath } : {}),
      },
    });
    closeSync(fd);
    let stderr = '';
    child.stdout?.resume();
    child.stderr?.on('data', (c) => {
      stderr += String(c);
    });
    child.on('close', (code) => resolve({ code, stderr, fileSize: statSync(payloadPath).size }));
  });
}

describe('#4770 a regular-file stdin that grows after the fstat keeps the 512KB cap', () => {
  it('control: without growth the small file is not refused for size', async () => {
    const { stderr, fileSize } = await runFileStdin(false);
    expect(fileSize).toBe(SMALL.length);
    expect(stderr).not.toMatch(SIZE_REFUSAL);
  });

  it('blocks (exit 2) a fail-closed gate when the file grows past 512KB after the fstat', async () => {
    const { code, stderr, fileSize } = await runFileStdin(true);
    // The preload really grew the file; otherwise the assertions below prove nothing.
    expect(fileSize).toBeGreaterThan(MAX_STDIN_BYTES);
    expect(stderr).toMatch(SIZE_REFUSAL);
    expect(code).toBe(2);
  });
});
